    @Test
    public void testCropRulingsToArea() {
        // Define a cropping area: x=10, y=10, width=100, height=100
        // Covers space from (10,10) to (110,110)
        Rectangle2D area = new Rectangle2D.Float(10, 10, 100, 100);
        
        List<Ruling> rulings = new ArrayList<>();
        
        // Case 1: Ruling completely inside the area
        // Top=20, Left=20, Width=50, Height=0 (Horizontal line)
        Ruling inside = new Ruling(20, 20, 50, 0);
        rulings.add(inside);
        
        // Case 2: Ruling intersecting the area (needs cropping)
        // Top=50, Left=0, Width=200, Height=0 (Horizontal line)
        // Starts at x=0 (outside), goes to x=200 (outside), passes through area (10 to 110)
        Ruling crossing = new Ruling(50, 0, 200, 0);
        rulings.add(crossing);
        
        // Case 3: Ruling completely outside the area
        // Top=5, Left=5, Width=4, Height=0
        Ruling outside = new Ruling(5, 5, 4, 0);
        rulings.add(outside);
        
        // Execute the focal method
        List<Ruling> result = Ruling.cropRulingsToArea(rulings, area);
        
        // Assertions
        Assert.assertNotNull(result);
        // Only the inside and the crossing ruling should remain
        Assert.assertEquals(2, result.size());
        
        // Verify the first ruling (was completely inside) remains unchanged
        Ruling res1 = result.get(0);
        Assert.assertEquals(20, res1.getTop(), 0.001);
        Assert.assertEquals(20, res1.getLeft(), 0.001);
        Assert.assertEquals(50, res1.getWidth(), 0.001);
        
        // Verify the second ruling (was crossing) is cropped to the area bounds
        // Original: x=0 to x=200. Area: x=10 to x=110.
        // Expected result: Left=10, Width=100 (ends at 110)
        Ruling res2 = result.get(1);
        Assert.assertEquals(50, res2.getTop(), 0.001); // Y stays same
        Assert.assertEquals(10, res2.getLeft(), 0.001); // Cropped to area left
        Assert.assertEquals(100, res2.getWidth(), 0.001); // Cropped to area width (110 - 10)
    }
